type SortDirection = "ascending" | "descending"
type SortValue = string | number | bigint | boolean | Date | null | undefined

interface DataTableSort {
  columnId: string
  direction: SortDirection
}

interface DataTablePage<Row> {
  rows: Row[]
  page: number
  pageCount: number
  total: number
}

type SelectionState = "none" | "some" | "all"

const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: "base" })

function isMissing(value: SortValue): value is null | undefined {
  return value === null || value === undefined || (typeof value === "number" && Number.isNaN(value))
}

function compareSortValues(a: SortValue, b: SortValue): number {
  if (typeof a === "string" && typeof b === "string") return collator.compare(a, b)
  const left = a instanceof Date ? a.getTime() : a
  const right = b instanceof Date ? b.getTime() : b
  if (left === right) return 0
  return (left as number) < (right as number) ? -1 : 1
}

// Missing values sort last in both directions, so a descending sort doesn't open on a page of blanks.
function sortRows<Row>(
  rows: readonly Row[],
  sort: DataTableSort | null | undefined,
  sortValue: ((row: Row) => SortValue) | undefined,
): Row[] {
  if (!sort || !sortValue) return [...rows]
  const sign = sort.direction === "ascending" ? 1 : -1
  return rows
    .map((row, index) => ({ row, index, value: sortValue(row) }))
    .toSorted((a, b) => {
      const missingA = isMissing(a.value)
      const missingB = isMissing(b.value)
      if (missingA || missingB) return missingA === missingB ? a.index - b.index : missingA ? 1 : -1
      return sign * compareSortValues(a.value, b.value) || a.index - b.index
    })
    .map((entry) => entry.row)
}

function nextSort(current: DataTableSort | null | undefined, columnId: string): DataTableSort {
  if (current?.columnId === columnId && current.direction === "ascending") return { columnId, direction: "descending" }
  return { columnId, direction: "ascending" }
}

function pageCountOf(total: number, pageSize: number | undefined): number {
  if (!pageSize || pageSize <= 0 || !Number.isFinite(pageSize)) return 1
  return Math.max(1, Math.ceil(total / pageSize))
}

function clampPage(page: number, pageCount: number): number {
  if (!Number.isFinite(page)) return 1
  return Math.min(Math.max(1, Math.trunc(page)), pageCount)
}

function paginate<Row>(rows: readonly Row[], page: number, pageSize: number | undefined): DataTablePage<Row> {
  const total = rows.length
  const pageCount = pageCountOf(total, pageSize)
  const current = clampPage(page, pageCount)
  if (pageCount === 1) return { rows: [...rows], page: current, pageCount, total }
  const size = pageSize as number
  return { rows: rows.slice((current - 1) * size, current * size), page: current, pageCount, total }
}

function selectionState(ids: readonly string[], selected: ReadonlySet<string>): SelectionState {
  if (ids.length === 0) return "none"
  const count = ids.reduce((sum, id) => sum + (selected.has(id) ? 1 : 0), 0)
  if (count === 0) return "none"
  return count === ids.length ? "all" : "some"
}

function toggleIds(selected: readonly string[], ids: readonly string[], checked: boolean): string[] {
  const next = new Set(selected)
  for (const id of ids) {
    if (checked) next.add(id)
    else next.delete(id)
  }
  return [...next]
}

export { clampPage, compareSortValues, nextSort, pageCountOf, paginate, selectionState, sortRows, toggleIds }
export type { DataTablePage, DataTableSort, SelectionState, SortDirection, SortValue }

import { createChange, createController, definePrimitive, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

import type { DataTableSort, SortDirection } from "@/lib/data-table-model"

type DataTableSortChangeReason = "item-press" | "imperative"
type DataTableSelectionChangeReason = "press" | "select-all" | "imperative"
type DataTablePageChangeReason =
  | "previous-press"
  | "next-press"
  | "first-press"
  | "last-press"
  | "item-press"
  | "imperative"

type DataTableItem = { value: string; label: string }

type DataTableOptions = {
  sortableColumns?: string[]
  rowItems?: DataTableItem[]
  pageCount?: number
  sort?: DataTableSort | null
  defaultSort?: DataTableSort | null
  onSortChange?: (sort: DataTableSort | null, details: ChangeDetails<DataTableSortChangeReason>) => void
  selection?: readonly string[]
  defaultSelection?: readonly string[]
  onSelectionChange?: (selection: string[], details: ChangeDetails<DataTableSelectionChangeReason>) => void
  page?: number
  defaultPage?: number
  onPageChange?: (page: number, details: ChangeDetails<DataTablePageChangeReason>) => void
  controller?: DataTableController
}

interface DataTableController {
  sortBy: (
    columnId: string | null,
    direction?: SortDirection,
    options?: ChangeOptions<DataTableSortChangeReason>,
  ) => boolean | undefined
  setSelection: (ids: string[], options?: ChangeOptions<DataTableSelectionChangeReason>) => boolean | undefined
  setPage: (page: number, options?: ChangeOptions<DataTablePageChangeReason>) => boolean | undefined
}

function reasonOf<Reason extends string>(options: unknown): { reason: Reason | "imperative"; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<Reason>
  return { reason, event: event instanceof Event ? event : undefined }
}

// The agent bridge passes action arguments unchecked, so every action validates its own.
const dataTable = definePrimitive({
  name: "data-table",
  options: {
    sortableColumns: "list",
    rowItems: "list",
    pageCount: "number",
    sort: "value",
    defaultSort: "value",
    onSortChange: "callback",
    selection: "list",
    defaultSelection: "list",
    onSelectionChange: "callback",
    page: "number",
    defaultPage: "number",
    onPageChange: "callback",
    controller: "value",
  },
  state: (options: DataTableOptions) => ({
    sort: options.sort !== undefined ? options.sort : (options.defaultSort ?? null),
    selection: options.selection ?? options.defaultSelection ?? [],
    page: options.page ?? options.defaultPage ?? 1,
  }),
  sync: (options) => ({
    ...(options.sort === undefined ? {} : { sort: options.sort }),
    ...(options.selection === undefined ? {} : { selection: options.selection }),
    ...(options.page === undefined ? {} : { page: options.page }),
  }),
  controlled: ["sort", "selection", "page"],
  api: (context) => {
    const change = createChange(context)
    return {
      sortBy(columnId: unknown, direction?: unknown, options?: ChangeOptions<DataTableSortChangeReason>) {
        if (columnId === null) return change("sort", null, reasonOf(options))
        const sortable = context.options().sortableColumns ?? []
        if (typeof columnId !== "string" || !sortable.includes(columnId)) {
          throw new RangeError(`Can't sort by "${String(columnId)}". Sortable columns: ${sortable.join(", ")}.`)
        }
        const current = context.store.get().sort
        const next: SortDirection =
          direction === "ascending" || direction === "descending"
            ? direction
            : current?.columnId === columnId && current.direction === "ascending"
              ? "descending"
              : "ascending"
        return change("sort", { columnId, direction: next }, reasonOf(options))
      },
      setSelection(ids: unknown, options?: ChangeOptions<DataTableSelectionChangeReason>) {
        const known = new Set((context.options().rowItems ?? []).map((item) => item.value))
        if (!Array.isArray(ids) || ids.some((id) => typeof id !== "string" || !known.has(id))) {
          throw new RangeError("setSelection takes a list of row ids from the table.")
        }
        return change("selection", [...new Set(ids as string[])], reasonOf(options))
      },
      setPage(page: unknown, options?: ChangeOptions<DataTablePageChangeReason>) {
        const pageCount = context.options().pageCount ?? 1
        if (typeof page !== "number" || !Number.isInteger(page) || page < 1 || page > pageCount) {
          throw new RangeError(`setPage takes a page from 1 to ${pageCount}.`)
        }
        return change("page", page, reasonOf(options))
      },
      rows: () => context.options().rowItems ?? [],
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "region",
      attrs: (state) => ({
        "data-sorted": state.sort ? "" : undefined,
        "data-selected": state.selection.length > 0 ? "" : undefined,
      }),
    }),
  }),
  agent: { actions: ["sortBy", "setSelection", "setPage"], items: (api) => api.rows() },
})

function createDataTableController() {
  return createController<DataTableController>()
}

export { createDataTableController, dataTable }
export type {
  DataTableController,
  DataTableItem,
  DataTableOptions,
  DataTablePageChangeReason,
  DataTableSelectionChangeReason,
  DataTableSortChangeReason,
}

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import type { ReactNode } from "react"
import { ChevronDownIcon, ChevronUpIcon, ChevronsUpDownIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Checkbox, CheckboxIndicator, type CheckedState } from "@/components/ui/checkbox"
import type {
  DataTableController,
  DataTablePageChangeReason,
  DataTableSelectionChangeReason,
  DataTableSortChangeReason,
} from "@/components/ui/data-table-primitive"
import { Pagination } from "@/components/ui/pagination"
import { TableHead } from "@/components/ui/table"
import type { DataTableSort, SortDirection, SortValue } from "@/lib/data-table-model"
import type { Virtualize } from "@/components/ui/virtual-rows"

type DataTableAlign = "start" | "center" | "end"

type DataTableColumn<Row> = {
  id: string
  header: ReactNode
  cell: (row: Row) => ReactNode
  sortValue?: (row: Row) => SortValue
  align?: DataTableAlign
}

type DataTableLabels = {
  sortBy: (header: string) => string
  selectAll: string
  selectRow: (rowLabel: string) => string
  previousPage: string
  nextPage: string
  pageStatus: (page: number, pageCount: number) => string
}

const dataTableLabels: DataTableLabels = {
  sortBy: (header) => `Sort by ${header}`,
  selectAll: "Select all rows on this page",
  selectRow: (rowLabel) => `Select ${rowLabel}`,
  previousPage: "Previous page",
  nextPage: "Next page",
  pageStatus: (page, pageCount) => `Page ${page} of ${pageCount}`,
}

type DataTablePageOptions = { reason?: DataTablePageChangeReason; event?: Event }

type DataTablePaginationProps = {
  page: number
  pageCount: number
  pageSize: number
  total: number
  onPageChange: (page: number, options?: DataTablePageOptions) => void
}

function SortIcon({ direction }: { direction?: SortDirection }) {
  if (direction === "ascending") return <ChevronUpIcon />
  if (direction === "descending") return <ChevronDownIcon />
  return <ChevronsUpDownIcon />
}

function DataTableHeaderCell<Row>({
  column,
  sort,
  sortLabel,
  onSort,
}: {
  column: DataTableColumn<Row>
  sort: DataTableSort | null
  sortLabel: DataTableLabels["sortBy"]
  onSort: (event: Event) => void
}) {
  const direction = sort?.columnId === column.id ? sort.direction : undefined
  const header = typeof column.header === "string" ? column.header : column.id
  return (
    <TableHead
      scope="col"
      aria-sort={column.sortValue ? (direction ?? "none") : undefined}
      data-align={column.align}
      className="data-[align=center]:text-center data-[align=end]:text-end"
    >
      {column.sortValue ? (
        <Button
          variant="ghost"
          size="sm"
          aria-label={sortLabel(header)}
          data-slot="data-table-sort"
          data-align={column.align}
          className="-mx-control-x gap-inline text-foreground data-[align=end]:flex-row-reverse [&_svg]:size-3.5"
          onClick={(event) => onSort(event.nativeEvent)}
        >
          {column.header}
          <SortIcon direction={direction} />
        </Button>
      ) : (
        column.header
      )}
    </TableHead>
  )
}

function DataTableCheckbox({
  label,
  checked,
  disabled,
  onChange,
}: {
  label: string
  checked: CheckedState
  disabled?: boolean
  onChange: (checked: boolean, event?: Event) => void
}) {
  return (
    <Checkbox
      aria-label={label}
      checked={checked}
      disabled={disabled}
      onCheckedChange={(next, details) => onChange(next === true, details.event)}
    >
      <CheckboxIndicator />
    </Checkbox>
  )
}

function DataTablePagination({
  page,
  pageCount,
  onPageChange,
  labels,
}: DataTablePaginationProps & { labels: Pick<DataTableLabels, "previousPage" | "nextPage" | "pageStatus"> }) {
  return (
    <div data-slot="data-table-pagination" className="flex flex-wrap items-center justify-end gap-items">
      <span className="text-sm text-muted-foreground tabular-nums" aria-live="polite">
        {labels.pageStatus(page, pageCount)}
      </span>
      <Pagination
        page={page}
        pageCount={pageCount}
        onPageChange={(next, details) => onPageChange(next, { reason: details.reason, event: details.event })}
        labels={{ previous: labels.previousPage, next: labels.nextPage }}
        className="w-auto"
      />
    </div>
  )
}

export { DataTableCheckbox, DataTableHeaderCell, dataTableLabels, DataTablePagination }
type DataTableProps<Row> = {
  label: string
  rows: readonly Row[]
  columns: readonly DataTableColumn<Row>[]
  getRowId: (row: Row) => string
  getRowLabel?: (row: Row) => string
  sort?: DataTableSort | null
  defaultSort?: DataTableSort | null
  onSortChange?: (sort: DataTableSort | null, details: ChangeDetails<DataTableSortChangeReason>) => void
  selectable?: boolean
  selection?: readonly string[]
  defaultSelection?: readonly string[]
  onSelectionChange?: (selection: string[], details: ChangeDetails<DataTableSelectionChangeReason>) => void
  pageSize?: number
  page?: number
  defaultPage?: number
  onPageChange?: (page: number, details: ChangeDetails<DataTablePageChangeReason>) => void
  renderPagination?: (props: DataTablePaginationProps) => ReactNode
  loading?: boolean
  loadingRows?: number
  empty?: ReactNode
  labels?: Partial<DataTableLabels>
  controller?: DataTableController
  /** Enter on a focused row. Rows are one tab stop: arrows or j/k move, Home/End and the page keys jump. */
  onRowOpen?: (row: Row) => void
  /** `"auto"` (default) renders only the rows in view past 200 rows. Bound the table's height to scroll inside it. */
  virtualize?: Virtualize
  /** A row's estimated height in px before it is measured. */
  estimateSize?: number
  className?: string
  tableClassName?: string
}

export type {
  DataTableAlign,
  DataTableColumn,
  DataTableLabels,
  DataTablePageOptions,
  DataTablePaginationProps,
  DataTableProps,
}

"use client"

import { useCallback, type ReactNode } from "react"

import { DataTableCheckbox, type DataTableColumn } from "@/components/ui/data-table-parts"
import { NavigableRow } from "@/components/ui/row-navigation"
import { Empty } from "@/components/ui/empty"
import { Skeleton } from "@/components/ui/skeleton"
import { TableCell, TableRow } from "@/components/ui/table"

type DataTableRowProps<Row> = {
  row: Row
  id: string
  columns: readonly DataTableColumn<Row>[]
  selection?: { label: string; selected: boolean; onChange: (checked: boolean, event?: Event) => void }
  /** The row's place among all rows, while the table is virtualized. */
  position?: { index: number; measure?: (node: HTMLElement | null) => void }
}

// The focus ring sits inside the row: a table row draws no box-shadow, and its outline would be clipped by the scroller.
const rowClassName =
  "scroll-mt-(--control-height) outline-none data-selected:bg-muted focus-visible:bg-muted/70 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring"

function DataTableRow<Row>({ row, id, columns, selection, position }: DataTableRowProps<Row>) {
  return (
    <NavigableRow
      id={id}
      render={<DataTableRowElement row={row} id={id} columns={columns} selection={selection} position={position} />}
    />
  )
}

function assignRef(ref: unknown, node: HTMLElement | null) {
  if (typeof ref === "function") return (ref as (node: HTMLElement | null) => unknown)(node)
  if (ref && typeof ref === "object") (ref as { current: unknown }).current = node
}

// Rendered by NavigableRow, which passes the roving tab stop's ref and handlers along with the row's own props.
function DataTableRowElement<Row>({
  row,
  id,
  columns,
  selection,
  position,
  ref,
  ...props
}: DataTableRowProps<Row> & { ref?: unknown } & Record<string, unknown>) {
  const measure = position?.measure
  const rowRef = useCallback(
    (node: HTMLTableRowElement | null) => {
      const cleanup = assignRef(ref, node)
      measure?.(node)
      return () => {
        if (typeof cleanup === "function") cleanup()
        else assignRef(ref, null)
      }
    },
    [ref, measure],
  )
  return (
    <TableRow
      {...props}
      ref={rowRef}
      data-index={position?.index}
      aria-rowindex={position ? position.index + 2 : undefined}
      data-row-id={id}
      data-selected={selection?.selected ? "" : undefined}
      className={rowClassName}
    >
      {selection && (
        <TableCell className="w-0">
          <DataTableCheckbox label={selection.label} checked={selection.selected} onChange={selection.onChange} />
        </TableCell>
      )}
      {columns.map((column) => (
        <TableCell
          key={column.id}
          data-align={column.align}
          className="data-[align=center]:text-center data-[align=end]:text-end"
        >
          {column.cell(row)}
        </TableCell>
      ))}
    </TableRow>
  )
}

function DataTableGapRow({ columns, size, children }: { columns: number; size: number; children?: ReactNode }) {
  return (
    <tr aria-hidden="true" data-slot="data-table-gap" style={{ height: size }}>
      <td colSpan={columns} className="p-0">
        {children}
      </td>
    </tr>
  )
}

function DataTableEmptyRow({ columns, children }: { columns: number; children?: ReactNode }) {
  return (
    <TableRow className="hover:bg-transparent">
      <TableCell colSpan={columns} className="max-w-none">
        {children !== undefined && <Empty className="border-0">{children}</Empty>}
      </TableCell>
    </TableRow>
  )
}

function DataTableLoadingRows({ rows, columns }: { rows: number; columns: number }) {
  return Array.from({ length: rows }, (_, row) => (
    <TableRow key={`loading-${row}`} data-slot="data-table-loading-row" className="hover:bg-transparent">
      {Array.from({ length: columns }, (_cell, column) => (
        <TableCell key={column}>
          <Skeleton className="h-4 w-full max-w-40" />
        </TableCell>
      ))}
    </TableRow>
  ))
}

export { DataTableEmptyRow, DataTableGapRow, DataTableLoadingRows, DataTableRow }
export type { DataTableRowProps }

"use client"

import { createParts } from "@ui-sdk/react/primitive"
import { useCallback, useMemo, useRef, useState } from "react"

import {
  DataTableCheckbox,
  DataTableHeaderCell,
  dataTableLabels,
  DataTablePagination,
  type DataTableColumn,
  type DataTableLabels,
  type DataTablePageOptions,
  type DataTablePaginationProps,
  type DataTableProps,
} from "@/components/ui/data-table-parts"
import { createDataTableController, dataTable } from "@/components/ui/data-table-primitive"
import { DataTableEmptyRow, DataTableGapRow, DataTableLoadingRows, DataTableRow } from "@/components/ui/data-table-row"
import { RowNavigationProvider, useRowNavigation } from "@/components/ui/row-navigation"
import { Table, TableBody, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import {
  clampPage,
  pageCountOf,
  paginate,
  selectionState,
  sortRows,
  toggleIds,
  type DataTableSort,
  type SortDirection,
  type SortValue,
} from "@/lib/data-table-model"
import { cn } from "@/lib/utils"
import { GapFindStubs, useVirtualRows } from "@/components/ui/virtual-rows"

const { Root: DataTableRoot } = createParts(dataTable, { root: "div" })

function useMirror<Value>(controlled: Value | undefined, initial: Value) {
  const [own, setOwn] = useState(initial)
  return [controlled === undefined ? own : controlled, setOwn] as const
}

// Stable between renders, so a virtualized table's find-in-page stubs re-render only when the rows change.
function useVisibleRows<Row>(
  rows: readonly Row[],
  columns: DataTableProps<Row>["columns"],
  sort: DataTableSort | null,
  page: number,
  pageSize: number | undefined,
) {
  return useMemo(() => {
    const sortValue = columns.find((column) => column.id === sort?.columnId)?.sortValue
    return paginate(sortRows(rows, sort, sortValue), page, pageSize).rows
  }, [rows, columns, sort, page, pageSize])
}

function DataTable<Row>({
  label,
  rows,
  columns,
  getRowId,
  getRowLabel = getRowId,
  selectable = false,
  pageSize,
  renderPagination,
  loading = false,
  loadingRows = 5,
  empty,
  labels: labelOverrides,
  controller: controllerProp,
  onRowOpen,
  virtualize = "auto",
  estimateSize = 41,
  className,
  tableClassName,
  ...state
}: DataTableProps<Row>) {
  const labels = { ...dataTableLabels, ...labelOverrides }
  const [ownController] = useState(createDataTableController)
  const controller = controllerProp ?? ownController
  const [sort, setSort] = useMirror(state.sort, state.defaultSort ?? null)
  const [selection, setSelection] = useMirror(state.selection, state.defaultSelection ?? [])
  const [requestedPage, setPage] = useMirror(state.page, state.defaultPage ?? 1)
  // Agent steps run back to back without a render in between, so a toggle builds on the selection the previous step
  // chose until a render shows a newer one.
  const chosen = useRef<{ shown: typeof selection; next: typeof selection } | null>(null)
  const latestSelection = () =>
    chosen.current !== null && chosen.current.shown === selection ? chosen.current.next : selection

  const pageCount = pageCountOf(rows.length, pageSize)
  const page = clampPage(requestedPage, pageCount)
  const visible = useVisibleRows(rows, columns, sort, page, pageSize)
  const visibleIds = useMemo(() => visible.map(getRowId), [visible, getRowId])
  const selected = new Set(selection)
  const pageSelection = selectionState(visibleIds, selected)
  const rowItems = rows.map((row) => ({ value: getRowId(row), label: getRowLabel(row) }))
  const columnCount = columns.length + (selectable ? 1 : 0)
  const indexOf = new Map(visibleIds.map((id, index) => [id, index]))

  const { anchor, ...virtual } = useVirtualRows({
    count: loading ? 0 : visible.length,
    virtualize,
    estimateSize,
    getKey: (index) => visibleIds[index] ?? String(index),
  })
  const textAt = useCallback(
    (index: number) => (visible[index] === undefined ? "" : getRowLabel(visible[index])),
    [visible, getRowLabel],
  )

  const toggleRow = (id: string, event?: Event) => {
    const checked = !latestSelection().includes(id)
    controller.setSelection(toggleIds(latestSelection(), [id], checked), { reason: "press", event })
  }
  const navigation = useRowNavigation({
    ids: visibleIds,
    onOpen: onRowOpen
      ? (id) => {
          const index = indexOf.get(id)
          if (index !== undefined && visible[index] !== undefined) onRowOpen(visible[index])
        }
      : undefined,
    onToggle: selectable ? (id, event) => toggleRow(id, event) : undefined,
    reveal: (id) => {
      const index = indexOf.get(id)
      if (index !== undefined) virtual.scrollToIndex(index)
    },
  })

  const pagination: DataTablePaginationProps = {
    page,
    pageCount,
    pageSize: pageSize ?? rows.length,
    total: rows.length,
    onPageChange: (next: number, options?: DataTablePageOptions) =>
      controller.setPage(clampPage(next, pageCount), options),
  }

  return (
    <DataTableRoot
      aria-label={label}
      controller={controller}
      sortableColumns={columns.filter((column) => column.sortValue).map((column) => column.id)}
      rowItems={rowItems}
      pageCount={pageCount}
      sort={sort}
      onSortChange={(next, details) => {
        state.onSortChange?.(next, details)
        if (!details.canceled) setSort(next)
      }}
      selection={selection}
      onSelectionChange={(next, details) => {
        state.onSelectionChange?.(next, details)
        if (details.canceled) return
        chosen.current = { shown: selection, next }
        setSelection(next)
      }}
      page={page}
      onPageChange={(next, details) => {
        state.onPageChange?.(next, details)
        if (!details.canceled) setPage(next)
      }}
      className={cn("flex w-full flex-col gap-items", className)}
    >
      <Table
        aria-label={label}
        aria-busy={loading || undefined}
        aria-rowcount={virtual.enabled ? visible.length + 1 : undefined}
        containerClassName="min-h-0"
        className={tableClassName}
      >
        <TableHeader className={cn(virtual.enabled && "[&_th]:sticky [&_th]:top-0 [&_th]:z-10 [&_th]:bg-background")}>
          <TableRow className="hover:bg-transparent">
            {selectable && (
              <TableHead scope="col" className="w-0">
                <DataTableCheckbox
                  label={labels.selectAll}
                  disabled={loading || visibleIds.length === 0}
                  checked={pageSelection === "some" ? "indeterminate" : pageSelection === "all"}
                  onChange={(checked, event) =>
                    controller.setSelection(toggleIds(latestSelection(), visibleIds, checked), {
                      reason: "select-all",
                      event,
                    })
                  }
                />
              </TableHead>
            )}
            {columns.map((column) => (
              <DataTableHeaderCell
                key={column.id}
                column={column}
                sort={sort}
                sortLabel={labels.sortBy}
                onSort={(event) => controller.sortBy(column.id, undefined, { reason: "item-press", event })}
              />
            ))}
          </TableRow>
        </TableHeader>
        <TableBody ref={anchor} className={cn(virtual.enabled && "relative")}>
          {loading ? (
            <DataTableLoadingRows rows={loadingRows} columns={columnCount} />
          ) : visible.length === 0 ? (
            <DataTableEmptyRow columns={columnCount}>{empty}</DataTableEmptyRow>
          ) : (
            <RowNavigationProvider handle={navigation}>
              {virtual.segments.map((segment) => {
                if (segment.type === "gap") {
                  return (
                    <DataTableGapRow key={segment.key} columns={columnCount} size={segment.size}>
                      <GapFindStubs
                        from={segment.from}
                        to={segment.to}
                        text={textAt}
                        offsetOf={virtual.offsetOf}
                        onFound={virtual.scrollToIndex}
                      />
                    </DataTableGapRow>
                  )
                }
                const row = visible[segment.index]
                const id = visibleIds[segment.index]
                if (row === undefined || id === undefined) return null
                return (
                  <DataTableRow
                    key={id}
                    row={row}
                    id={id}
                    columns={columns}
                    position={virtual.enabled ? { index: segment.index, measure: virtual.measureElement } : undefined}
                    selection={
                      selectable
                        ? {
                            label: labels.selectRow(getRowLabel(row)),
                            selected: selected.has(id),
                            onChange: (checked, event) =>
                              controller.setSelection(toggleIds(latestSelection(), [id], checked), {
                                reason: "press",
                                event,
                              }),
                          }
                        : undefined
                    }
                  />
                )
              })}
            </RowNavigationProvider>
          )}
        </TableBody>
      </Table>
      {pageSize !== undefined &&
        pageCount > 1 &&
        (renderPagination ? renderPagination(pagination) : <DataTablePagination {...pagination} labels={labels} />)}
    </DataTableRoot>
  )
}

export { createDataTableController, DataTable, dataTableLabels }
export type { DataTableColumn, DataTableLabels, DataTablePaginationProps, DataTableProps }
export type { DataTableSort, SortDirection, SortValue }
